std::string uuid(){GUID value{};hcheck(CoCreateGuid(&value),"Create identifier");wchar_t text[40]{};StringFromGUID2(value,text,40);auto s=utf8(text);std::erase_if(s,[](char c){return c=='{'||c=='}'||c=='-';});return s;}
void private_directory(const fs::path& dir){fs::create_directories(dir);Handle token;HANDLE raw=nullptr;check(OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&raw)!=FALSE,"Open process token");token.reset(raw);DWORD n=0;GetTokenInformation(token.get(),TokenUser,nullptr,0,&n);Bytes storage(n);check(GetTokenInformation(token.get(),TokenUser,storage.data(),n,&n)!=FALSE,"Read user SID");LPWSTR sid=nullptr;check(ConvertSidToStringSidW(reinterpret_cast<TOKEN_USER*>(storage.data())->User.Sid,&sid)!=FALSE,"Format user SID");std::wstring descriptor=L"D:P(A;OICI;FA;;;";descriptor+=sid;descriptor+=L")";LocalFree(sid);PSECURITY_DESCRIPTOR security=nullptr;check(ConvertStringSecurityDescriptorToSecurityDescriptorW(descriptor.c_str(),SDDL_REVISION_1,&security,nullptr)!=FALSE,"Create private ACL");auto ok=SetFileSecurityW(dir.c_str(),DACL_SECURITY_INFORMATION|PROTECTED_DACL_SECURITY_INFORMATION,security);LocalFree(security);check(ok!=FALSE,"Apply private ACL");}
void atomic_write(const fs::path& path,std::span<const unsigned char> bytes){fs::create_directories(path.parent_path());auto temporary=path;temporary+=L"."+wide(uuid())+L".tmp";try{Handle f(CreateFileW(temporary.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));check(static_cast<bool>(f),"Create atomic file");size_t cursor=0;while(cursor<bytes.size()){DWORD written=0;auto count=static_cast<DWORD>(std::min<size_t>(bytes.size()-cursor,1024*1024));check(WriteFile(f.get(),bytes.data()+cursor,count,&written,nullptr)!=FALSE&&written!=0,"Write atomic file");cursor+=written;}check(FlushFileBuffers(f.get())!=FALSE,"Flush atomic file");f.reset();check(MoveFileExW(temporary.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)!=FALSE,"Commit atomic file");}catch(...){std::error_code e;fs::remove(temporary,e);throw;}}
void Session::validate()const{
 if(name.empty()||name.size()>600)throw std::runtime_error("请填写会话名称。");
 if(host.empty()||host.front()=='-'||std::any_of(host.begin(),host.end(),[](unsigned char c){return c<=32||c==127||c=='"'||c=='/'||c=='\\'||c=='@';}))throw std::runtime_error("请填写有效主机名或 IP。");
 if(port<1||port>65535)throw std::runtime_error("端口应在 1–65535 之间。");
 if(std::any_of(user.begin(),user.end(),[](unsigned char c){return c<32||c==127;}))throw std::runtime_error("用户名包含控制字符。");
 if(auth!="agent"&&auth!="password"&&auth!="ask")throw std::runtime_error("未知认证方式。");
 (void)wide(host);(void)wide(user);(void)wide(name);
}
void to_json(Json&j,const Session&s){j=Json{{"Id",s.id},{"Name",s.name},{"Group",s.group},{"Host",s.host},{"Port",s.port},{"User",s.user},{"Auth",s.auth},{"CredentialId",s.credential_id},{"KeyFile",s.key_file},{"RemoteDirectory",s.remote_directory},{"Bookmarks",s.bookmarks},{"PuttyProfile",s.putty_profile},{"Source",s.source}};}
void from_json(const Json&j,Session&s){s.id=j.value("Id",uuid());s.name=j.value("Name","");s.group=j.value("Group","默认");s.host=j.value("Host","");s.port=j.value("Port",22);s.user=j.value("User","");s.auth=j.value("Auth","agent");s.credential_id=j.value("CredentialId","");s.key_file=j.value("KeyFile","");s.remote_directory=j.value("RemoteDirectory","");s.bookmarks=j.contains("Bookmarks")&&!j["Bookmarks"].is_null()?j["Bookmarks"].get<std::vector<std::string>>():std::vector<std::string>{};s.putty_profile=j.value("PuttyProfile","");s.source=j.value("Source","");s.validate();}
static Json load_json(const fs::path&p){auto bytes=read_bytes(p);if(bytes.size()>16*1024*1024)throw std::runtime_error("配置文件超过大小限制。");return Json::parse(bytes);}
static void save_json(const fs::path&p,const Json&j){auto text=j.dump(2);atomic_write(p,{reinterpret_cast<const unsigned char*>(text.data()),text.size()});}
SessionStore::SessionStore(fs::path dir):directory(std::move(dir)){private_directory(directory);auto p=directory/L"sessions.json";if(fs::exists(p)){auto j=load_json(p);if(j.at("Version")!=1)throw std::runtime_error("会话库版本不支持。");sessions=j.at("Sessions").get<std::vector<Session>>();groups=j.at("Groups").get<std::vector<std::string>>();}}
void SessionStore::save()const{save_json(directory/L"sessions.json",Json{{"Version",1},{"Groups",groups},{"Sessions",sessions}});}
void SessionStore::export_to(const fs::path&p)const{auto sanitized=sessions;for(auto&s:sanitized){s.credential_id.clear();if(s.auth=="password")s.auth="ask";}save_json(p,Json{{"Version",1},{"Groups",groups},{"Sessions",sanitized}});}
size_t SessionStore::import_from(const fs::path&p){auto j=load_json(p);if(j.at("Version")!=1)throw std::runtime_error("导入版本不支持。");auto incoming=j.at("Sessions").get<std::vector<Session>>();auto imported_groups=j.value("Groups",std::vector<std::string>{});for(const auto&group:imported_groups)if(std::find(groups.begin(),groups.end(),group)==groups.end())groups.push_back(group);for(auto&s:incoming){s.id=uuid();s.credential_id.clear();if(s.auth=="password")s.auth="ask";if(std::find(groups.begin(),groups.end(),s.group)==groups.end())groups.push_back(s.group);}sessions.insert(sessions.end(),incoming.begin(),incoming.end());save();return incoming.size();}
std::wstring quote(std::wstring_view text){std::wstring out=L"\"";size_t slashes=0;for(wchar_t c:text){if(c=='\\'){++slashes;continue;}out.append(c=='"'?slashes*2+1:slashes,L'\\');out+=c;slashes=0;}out.append(slashes*2,L'\\');return out+L'"';}
std::wstring command_line(const std::vector<std::wstring>&args){std::wstring result;for(auto&a:args){if(!result.empty())result+=L' ';result+=quote(a);}return result;}
std::string uri_encode(std::string_view text){constexpr char hex[]="0123456789ABCDEF";std::string out;for(unsigned char c:text){if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.'||c=='~')out+=static_cast<char>(c);else{out+='%';out+=hex[c>>4];out+=hex[c&15];}}return out;}
std::wstring putty_profile_key(std::string_view name){
 auto value=wide(name);if(value.empty()||std::any_of(value.begin(),value.end(),[](wchar_t ch){return ch<32;}))throw std::runtime_error("PuTTY 会话名称为空或包含控制字符。");
 BOOL substituted=FALSE;const bool unicode=GetACP()==CP_UTF8;auto flags=unicode?0:WC_NO_BEST_FIT_CHARS;
 auto n=WideCharToMultiByte(CP_ACP,flags,value.data(),static_cast<int>(value.size()),nullptr,0,nullptr,unicode?nullptr:&substituted);check(n>0,"Encode native PuTTY session name");std::string bytes(static_cast<size_t>(n),0);
 check(WideCharToMultiByte(CP_ACP,flags,value.data(),static_cast<int>(value.size()),bytes.data(),n,nullptr,unicode?nullptr:&substituted)>0,"Encode native PuTTY session name");if(substituted)throw std::runtime_error("PuTTY 原生会话名称无法用当前 Windows 代码页表示，请使用兼容名称。");
 std::string encoded;constexpr char hex[]="0123456789ABCDEF";for(unsigned char ch:bytes){if(ch==' '||ch=='\\'||ch=='*'||ch=='?'||ch=='%'||ch<32||ch>126||(ch=='.'&&encoded.empty())){encoded+='%';encoded+=hex[ch>>4];encoded+=hex[ch&15];}else encoded+=static_cast<char>(ch);}if(encoded.size()>255)throw std::runtime_error("PuTTY 原生会话名称过长。");return wide(encoded);
}
std::string putty_profile_name(std::wstring_view key){
 auto encoded=utf8(key);std::string bytes;auto hex=[](char ch){if(ch>='0'&&ch<='9')return ch-'0';if(ch>='A'&&ch<='F')return ch-'A'+10;if(ch>='a'&&ch<='f')return ch-'a'+10;return -1;};
 for(size_t i=0;i<encoded.size();++i){if(encoded[i]=='%'&&i+2<encoded.size()&&hex(encoded[i+1])>=0&&hex(encoded[i+2])>=0){bytes+=static_cast<char>((hex(encoded[i+1])<<4)|hex(encoded[i+2]));i+=2;}else bytes+=encoded[i];}
 auto n=MultiByteToWideChar(CP_ACP,MB_ERR_INVALID_CHARS,bytes.data(),static_cast<int>(bytes.size()),nullptr,0);check(n>0,"Decode native PuTTY session name");std::wstring value(static_cast<size_t>(n),0);check(MultiByteToWideChar(CP_ACP,MB_ERR_INVALID_CHARS,bytes.data(),static_cast<int>(bytes.size()),value.data(),n)>0,"Decode native PuTTY session name");return utf8(value);
}
ConnectionContext snapshot(const Session&s){s.validate();ConnectionContext c{s};if(s.putty_profile.empty())return c;
 HKEY key=nullptr;auto path=L"Software\\SimonTatham\\PuTTY\\Sessions\\"+putty_profile_key(s.putty_profile);if(RegOpenKeyExW(HKEY_CURRENT_USER,path.c_str(),0,KEY_READ,&key)!=ERROR_SUCCESS){c.unsupported_reason="原 PuTTY 会话已不存在，请重新关联或保存会话。";return c;}
 auto integer=[&](const wchar_t*name,int fallback){DWORD value=0,n=sizeof(value);if(RegGetValueW(key,nullptr,name,RRF_RT_REG_DWORD,nullptr,&value,&n)!=ERROR_SUCCESS)return fallback;return static_cast<int>(value);};
 auto text=[&](const wchar_t*name){DWORD n=0;if(RegGetValueW(key,nullptr,name,RRF_RT_REG_SZ,nullptr,nullptr,&n)!=ERROR_SUCCESS||n>65536)return std::string{};std::vector<wchar_t>b(n/2+1);if(RegGetValueW(key,nullptr,name,RRF_RT_REG_SZ,nullptr,b.data(),&n)!=ERROR_SUCCESS)return std::string{};return utf8(b.data());};
 c.proxy_method=integer(L"ProxyMethod",0);c.proxy_host=text(L"ProxyHost");c.proxy_user=text(L"ProxyUsername");c.proxy_port=integer(L"ProxyPort",80);
 if(c.proxy_method!=0)c.unsupported_reason="此会话使用 PuTTY 代理/跳板配置。WinSCP 需要先显式配置对应站点，不能静默直连。";
 if(!text(L"ProxyTelnetCommand").empty()&&c.proxy_method>0)c.unsupported_reason="此会话含代理命令，请在 WinSCP 中显式配置后打开。";
 RegCloseKey(key);return c;
}
std::vector<std::wstring> plink_arguments(const ConnectionContext&c,std::wstring_view profile,std::wstring_view password_pipe,bool share){c.session.validate();if(profile.empty())throw std::runtime_error("Plink 必须关联已保存的 PuTTY 会话。");std::vector<std::wstring>a{L"-load",std::wstring(profile),L"-ssh",L"-P",std::to_wstring(c.session.port),L"-t",share?L"-share":L"-noshare",L"-no-sanitise-stdout",L"-no-sanitise-stderr"};if(!c.session.user.empty()){a.emplace_back(L"-l");a.push_back(wide(c.session.user));}a.push_back(c.session.auth=="agent"?L"-agent":L"-noagent");if(c.session.auth=="agent"&&!c.session.key_file.empty()){a.emplace_back(L"-i");a.push_back(wide(c.session.key_file));}if(!password_pipe.empty()){a.emplace_back(L"-pwfile");a.emplace_back(password_pipe);}return a;}
std::vector<std::wstring> winscp_arguments(const ConnectionContext&c,const fs::path&config,std::wstring_view password_pipe){if(!c.unsupported_reason.empty())throw std::runtime_error(c.unsupported_reason);const auto&s=c.session;s.validate();auto host=s.host.find(':')!=std::string::npos?"["+s.host+"]":s.host;std::string url="sftp://"+(s.user.empty()?"":uri_encode(s.user)+"@")+host+":"+std::to_string(s.port)+"/";if(!s.remote_directory.empty()){auto path=s.remote_directory;while(!path.empty()&&path.front()=='/')path.erase(path.begin());size_t start=0;while(start<path.size()){auto end=path.find('/',start);if(end==std::string::npos)end=path.size();url+=uri_encode(std::string_view(path).substr(start,end-start))+"/";start=end+1;}}
 std::vector<std::wstring>a{wide(url),L"/newinstance",L"/ini="+config.wstring(),L"/sessionname="+wide(s.name)};if(s.auth=="agent"&&!s.key_file.empty())a.push_back(L"/privatekey="+wide(s.key_file));if(!password_pipe.empty()){a.emplace_back(L"/passwordsfromfiles");a.push_back(L"/password="+std::wstring(password_pipe));}a.emplace_back(L"/rawsettings");a.push_back(s.auth=="agent"?L"TryAgent=1":L"TryAgent=0");return a;
}
bool Process::running()const{return process&&WaitForSingleObject(process.get(),0)==WAIT_TIMEOUT;}DWORD Process::exit_code()const{DWORD result=0;check(GetExitCodeProcess(process.get(),&result)!=FALSE,"Read process status");return result;}
Process start_process(const fs::path&exe,const std::vector<std::wstring>&args,DWORD flags,STARTUPINFOEXW* extended,std::wstring_view raw_tail){auto all=args;all.insert(all.begin(),exe.wstring());auto cmd=command_line(all);if(!raw_tail.empty()){cmd+=L' ';cmd+=raw_tail;}STARTUPINFOW ordinary{};ordinary.cb=sizeof(ordinary);PROCESS_INFORMATION p{};STARTUPINFOW* startup=extended?&extended->StartupInfo:&ordinary;if(extended)flags|=EXTENDED_STARTUPINFO_PRESENT;auto temp=root()/L"runtime/temp";private_directory(temp);std::vector<std::wstring> variables;auto environment=GetEnvironmentStringsW();check(environment!=nullptr,"Read child environment");for(auto entry=environment;*entry;entry+=wcslen(entry)+1){std::wstring value(entry);if(_wcsnicmp(value.c_str(),L"TEMP=",5)!=0&&_wcsnicmp(value.c_str(),L"TMP=",4)!=0)variables.push_back(std::move(value));}FreeEnvironmentStringsW(environment);variables.push_back(L"TEMP="+temp.wstring());variables.push_back(L"TMP="+temp.wstring());std::sort(variables.begin(),variables.end(),[](const auto&a,const auto&b){return _wcsicmp(a.c_str(),b.c_str())<0;});std::vector<wchar_t> block;for(auto&value:variables){block.insert(block.end(),value.begin(),value.end());block.push_back(0);}block.push_back(0);check(CreateProcessW(exe.c_str(),cmd.data(),nullptr,nullptr,FALSE,flags|CREATE_UNICODE_ENVIRONMENT,block.data(),exe.parent_path().c_str(),startup,&p)!=FALSE,"Create component process");return {Handle(p.hProcess),Handle(p.hThread),p.dwProcessId};}
